deepml vfx 0.3
module corpus.deepml_vfx.example_03001
policy deterministic
policy no_network
effect Effect03001 {
  coupled simulation PortalSim seed 3001 { fluid: Energy cloth: Veil particles: Sparks }
  procedural operator Distort(time, portal_state) differentiable
  cache PortalCache9 interval 0s..10s step 1/60s hash sha256("cache:03001")
  bind scene PortalScene9
  bind timeline PortalSequence11
  render_graph { Sim -> Lighting -> Distortion -> Composite }
  composite multipass [SceneColor, PortalGlow, Distortion, Atmosphere]
}

